  cycle_nudge_fertility_menstruation_body: "El día uno reinicia el reloj. Tu próxima ventana fértil es en aproximadamente dos semanas — un período tranquilo para descansar y prepararte antes de que se abra.",
  cycle_nudge_reflect_mood_headline: "¿Cómo te *sientes* hoy?",
  cycle_nudge_reflect_mood_body: "Un rápido chequeo de estado de ánimo construye la imagen con el tiempo — los patrones por fase son más fáciles de ver una vez que tienes algunos ciclos registrados.",
  cycle_nudge_reflect_symptom_headline: "¿Notando *algo* hoy?",
  cycle_nudge_reflect_symptom_body: "¿Calambres, senos sensibles, un dolor de cabeza? Registrar síntomas te ayuda a ti y a tu médico a detectar qué es típico para ti y qué no.",
  cycle_nudge_reflect_energy_headline: "¿Dónde está tu *energía*?",
  cycle_nudge_reflect_energy_body: "La energía naturalmente baja antes de tu período. Anotarlo hoy te ayuda a planificar alrededor de tu propio ritmo en lugar de luchar contra él.",
  cycle_nudge_nutrition_luteal_headline: "Busca *magnesio*",
  cycle_nudge_nutrition_luteal_body: "Chocolate negro, almendras, semillas de calabaza y plátanos alivian calambres y estabilizan el estado de ánimo en la segunda mitad del ciclo. Combina con carbohidratos complejos para suavizar los antojos.",
  cycle_nudge_nutrition_ovulation_headline: "Alimenta el *óvulo*",
  cycle_nudge_nutrition_ovulation_body: "Alimentos ricos en antioxidantes — bayas, verduras de hoja verde, nueces — apoyan la calidad del óvulo. El zinc (semillas de calabaza, garbanzos) es más importante alrededor de la ovulación.",
  cycle_nudge_edu_menstruation_headline: "Tu período es el *primer* día",
  cycle_nudge_edu_menstruation_body: "El día del ciclo uno es el primer día de sangrado real, no manchado. Ese es el ancla desde el que se cuentan todas las predicciones — así que registrarlo con precisión agudiza todo.",
  cycle_nudge_edu_follicular_headline: "Un folículo *gana*",
  cycle_nudge_edu_follicular_body: "Varios folículos comienzan a crecer cada ciclo, pero generalmente solo uno madura y libera un óvulo. El estrógeno creciente es lo que impulsa esa selección.",
  cycle_nudge_edu_ovulation_headline: "Un evento de *36 horas*",
  cycle_nudge_edu_ovulation_body: "La ovulación en sí es breve — el pico de LH desencadena la liberación dentro de ~24–36 horas. Por eso las tiras de LH se cronometran para captar el pico, no la liberación.",
  cycle_nudge_edu_luteal_headline: "La *espera de dos semanas*",
  cycle_nudge_edu_luteal_body: "La fase luteal es notablemente constante — generalmente 12–14 días independientemente de la duración del ciclo. La mayoría de la variación del ciclo proviene de la primera mitad, no de esta.",
  cycle_pillar_fertility: "Conceptos de Fertilidad",
