  dataTrans_title: "Cómo usamos tus datos",
  dataTrans_subtitle: "en lenguaje sencillo",
  dataTrans_intro: "Nos confías información sensible. Aquí está exactamente qué recopilamos y por qué — y, igual de importante, qué nunca haremos con ella.",
  dataTrans_sectionCollect: "Qué recopilamos y por qué",
  dataTrans_healthTitle: "Datos de salud y ciclo",
  dataTrans_healthBody: "Reglas, síntomas, semanas de embarazo, peso y ánimo — usados solo para tu seguimiento, tus insights y la guía de Grandma. Siguen siendo tuyos.",
  dataTrans_childTitle: "Información de los hijos",
  dataTrans_childBody: "Nombres, fechas de nacimiento, crecimiento, alimentación, sueño y registros médicos — usados para personalizar el camino de tu hijo y compartir con el círculo de cuidado que elijas.",
  dataTrans_accountTitle: "Datos de la cuenta",
  dataTrans_accountBody: "Tu correo y tu inicio de sesión sirven para proteger tu cuenta y sincronizar tus datos entre dispositivos. Nada más.",
  dataTrans_aiTitle: "Chats con Grandma",
  dataTrans_aiBody: "Tus preguntas le dan contexto a Grandma para responder bien. Puedes desactivar el uso de datos por la IA y borrar tu historial de chat cuando quieras.",
  dataTrans_photosTitle: "Fotos y escaneos",
  dataTrans_photosBody: "Las fotos que añades a los recuerdos o escaneas para obtener insights se guardan de forma privada para ti y solo se comparten con tu círculo de cuidado cuando lo permitas.",
  dataTrans_usageTitle: "Uso de la app",
  dataTrans_usageBody: "El uso anónimo y agregado nos ayuda a corregir errores y mejorar la app. Puedes desactivarlo en Datos y privacidad → Analíticas.",
  dataTrans_sectionNever: "Nunca",
  dataTrans_never1: "Vendemos tus datos personales a nadie.",
  dataTrans_never2: "Compartimos tus datos de salud o los de tus hijos sin tu permiso.",
  dataTrans_never3: "Usamos tus datos privados para entrenar IA de terceros.",
  dataTrans_never4: "Conservamos tus datos después de que eliminas tu cuenta.",
  dataTrans_footer: "Tus datos están cifrados en reposo y en tránsito. Lee la Política de Privacidad completa cuando quieras en Datos y privacidad → Legal.",
  about_title: "Acerca de grandma.app",
  about_tagline: "tu compañera de confianza",
  about_missionTitle: "Nuestra misión",
  about_missionBody: "Ser la presencia tranquila y sabia al lado de cada madre y padre — desde la búsqueda, pasando por el embarazo, hasta los primeros años. Un apoyo que se siente como familia.",
  about_expertiseTitle: "Con base en expertos",
  about_expertiseBody: "La guía de Grandma se apoya en el conocimiento de ginecólogos, matronas y pediatras. Es un apoyo cariñoso — nunca un sustituto de tu propio médico.",
  about_privacyTitle: "La privacidad primero",
  about_privacyBody: "Tus datos de salud y de familia son tuyos. Mira exactamente qué recopilamos y por qué.",
  about_privacyPolicy: "Política de Privacidad",
  about_terms: "Términos de Uso",
  about_help: "Ayuda y preguntas frecuentes",
  about_contact: "Escríbenos",
  about_copyright: "© 2026 grandma.app. Hecho con cariño.",
  help_title: "Ayuda y preguntas frecuentes",
  help_subtitle: "aquí estamos para ti",
  help_searchPlaceholder: "¿Qué te gustaría encontrar?",
  help_noResults: "No encontramos respuestas. Prueba con otras palabras o escríbenos abajo.",
  help_stillStuck: "¿Necesitas una mano?",
  help_stillStuckBody: "¿No encuentras tu respuesta? Nuestro equipo estará feliz de ayudarte.",
  help_contactUs: "Escríbenos",
  help_catStart: "Primeros pasos",
  help_catAccount: "Cuenta y datos",
  help_catCare: "Círculo de Cuidado",
  help_catAi: "Grandma IA",
  help_catBilling: "Suscripciones y facturación",
  help_catPrivacy: "Privacidad",
  help_q_modes: "¿Qué son los modos de camino?",
  help_a_modes: "grandma.app se adapta a tu momento: Ciclo (seguir tu ciclo o buscar embarazo), Embarazo, Hijos (crianza de 0 a 5 años) y Menopausia. Cada etapa cambia tu inicio, lo que registras y la guía de Grandma.",
  help_q_switchMode: "¿Cómo cambio de modo?",
  help_a_switchMode: "Abre la pestaña Ajustes y toca una etapa en Mis etapas. Cada etapa guarda sus propios datos, así que no se pierde nada al cambiar.",
  help_q_logging: "¿Cómo registro algo?",
  help_a_logging: "Registra desde tu inicio o la pestaña Calendario: elige el día y qué anotar — regla, síntomas, ánimo, sueño y más. Todo aparece en tu calendario y en tus Notas.",
  help_q_export: "¿Cómo exporto mis datos?",
  help_a_export: "Ve a Ajustes → Datos y privacidad → Datos que guardamos → Exportar todos mis datos. Recibirás una copia completa en JSON, legible por máquina, de todo lo que guardamos.",
  help_q_delete: "¿Cómo elimino mi cuenta?",
  help_a_delete: "Ajustes → Cuenta → Eliminar cuenta. Esto borra tus datos de nuestros sistemas de forma permanente y no se puede deshacer.",
  help_q_password: "¿Cómo cambio mi contraseña?",
  help_a_password: "Ajustes → Cuenta → Cambiar contraseña. Si entraste con Apple o Google, gestiona tu acceso desde ese proveedor.",
  help_q_invite: "¿Cómo invito a mi círculo de cuidado?",
  help_a_invite: "Ajustes → Círculo de Cuidado → Invitar. Envía un enlace seguro a tu pareja, niñera o abuelo/a. Se unen con los permisos exactos que elijas.",
  help_q_permissions: "¿Puedo controlar lo que ven los cuidadores?",
  help_a_permissions: "Sí. Cada cuidador tiene permisos que tú defines — decides quién puede ver o añadir registros, datos de salud y más. Cambia o revoca el acceso cuando quieras.",
  help_q_grandma: "¿Quién es Grandma?",
  help_a_grandma: "Grandma es tu compañera de IA, impulsada por Claude. Responde con el contexto de tu camino y ofrece una guía cálida y práctica de día o de noche.",
  help_q_medical: "¿El consejo de Grandma es un consejo médico?",
  help_a_medical: "No. Grandma ofrece una guía cariñosa y educativa — no diagnóstico ni tratamiento. Consulta siempre a tu médico, matrona o pediatra ante dudas de salud.",
  help_q_premium: "¿Qué incluye Premium?",
  help_a_premium: "Premium desbloquea escaneos y chat ilimitados, insights completos y recordatorios. Puedes suscribirte mensual o anualmente.",
  help_q_cancel: "¿Cómo cancelo Premium?",
  help_a_cancel: "Gestiona o cancela tu suscripción cuando quieras en los ajustes de tu cuenta de la tienda de apps. Tus funciones Premium siguen activas hasta el final del periodo de facturación.",
  help_q_dataSafe: "¿Mis datos están seguros?",
  help_a_dataSafe: "Sí. Tus datos están cifrados en tránsito y en reposo, y protegidos con seguridad a nivel de fila para que solo tú y el círculo de cuidado que elijas tengan acceso.",
  help_q_sell: "¿Venden mis datos?",
  help_a_sell: "Nunca. No vendemos tus datos personales y jamás usamos tus datos privados de salud o de tus hijos para entrenar IA de terceros.",
  legal_contents: "Contenido",
  legal_hostedPrefix: "Consulta la política completa en",
  safety_report: "Denunciar",
  safety_block: "Bloquear usuaria",
