  safety_reason_self_harm: "Autolesión o peligro",
  safety_reason_other: "Otro motivo",
  guidelines_title: "Normas de la comunidad",
  guidelines_subtitle: "un lugar amable para compartir",
  guidelines_intro: "grandma.app es un espacio para que madres y padres se apoyen con sinceridad. Para mantenerlo seguro para todos, te pedimos seguir unas reglas sencillas.",
  guidelines_rule1Title: "Sé amable y respetuosa",
  guidelines_rule1Body: "Cada persona aquí vive su propio camino. Nada de acoso, bullying, discurso de odio ni ataques personales.",
  guidelines_rule2Title: "Protege la privacidad",
  guidelines_rule2Body: "No compartas información personal o de salud de otras personas. Piensa también en lo que cuentas de tu propia familia.",
  guidelines_rule3Title: "Ofrece apoyo, no diagnóstico",
  guidelines_rule3Body: "Comparte experiencia y ánimo — no indicaciones médicas. Ante dudas de salud, remite siempre al médico.",
  guidelines_rule4Title: "Sin spam ni ventas",
  guidelines_rule4Body: "Mantén la comunidad para conectar, no para promocionar. Los anuncios del mercado van en el intercambio, no en el feed.",
  guidelines_rule5Title: "Mantén todo seguro",
  guidelines_rule5Body: "Nada que promueva la autolesión, el peligro para los niños o cualquier cosa ilegal. Lo eliminamos y podemos suspender la cuenta.",
  guidelines_sectionReport: "Si ves algo",
  guidelines_reportBody: "Mantén pulsada cualquier publicación o mensaje para denunciarlo o bloquear a la persona. Las denuncias son privadas y las revisa nuestro equipo. En una emergencia, contacta siempre a los servicios de emergencia locales.",
  guidelines_footer: "Incumplir estas reglas puede llevar a la eliminación de contenido o a la suspensión de la cuenta. Gracias por mantener segura esta comunidad.",
