  sw2_leap19_name: "Eventos",
  sw2_leap19_desc: "Entender que las acciones ocurren en secuencia",
  sw2_leap19_brain: "Por esta etapa, los bebés suelen empezar a ver el mundo como una serie de sucesos y no como un gran borrón. Las acciones tienen principio, medio y final. Es el comienzo del pensamiento de causa y efecto, y por eso todo puede parecer de pronto fascinante.",
  sw2_leap19_tip: "Juega a juegos sencillos de causa y efecto, como el cu-cú — el bebé está aprendiendo que los sucesos tienen resultados predecibles.",
  sw2_leap19_ph0: "Muy pegado, llora al dejarlo, sueño alterado. El bebé puede sentirse agotado con tantas novedades a la vez.",
  sw2_leap19_ph1: "El bebé suele estar ocupado uniendo cada acción con lo que pasa después: empujar, soltar, mirar con atención.",
  sw2_leap19_ph2: "Aparece el alcance intencional y las primeras señales de permanencia del objeto: el bebé busca lo que se cae.",
  sw2_leap19_sg0: "Más ansiedad por separación",
  sw2_leap19_sg1: "Muy pegado",
  sw2_leap19_sg2: "Llora cuando se cae un juguete",
  sw2_leap19_sg3: "Se resiste a las siestas",
  sw2_leap19_sg4: "Reclama atención constante",
  sw2_leap19_sg5: "Se frustra si cambia la rutina",
  sw2_leap19_sk0: "Alcanza y agarra a propósito",
  sw2_leap19_sk1: "Sacude y golpea juguetes",
  sw2_leap19_sk2: "Reconoce los juegos",
  sw2_leap19_sk3: "Entiende «arriba» y «abajo»",
  sw2_leap19_sk4: "Sigue con la mirada los objetos en movimiento",
  sw2_leap19_sk5: "Se ríe con las sorpresas",
  sw2_leap19_ac0: "Juegos de cu-cú y de esconderse",
  sw2_leap19_ac1: "Rodar una pelota de ida y vuelta",
  sw2_leap19_ac2: "Juguetes sencillos de causa y efecto (pulsar = sonido)",
  sw2_leap19_ac3: "Narra la rutina diaria paso a paso",
  sw2_leap5_name: "Sensaciones que cambian",
  sw2_leap5_desc: "El bebé descubre un mundo más rico de sentidos",
  sw2_leap5_brain: "Por esta época, tu bebé puede empezar a notar muchos más detalles con los sentidos: imágenes más nítidas, sonidos más ricos, nuevas sensaciones en el cuerpo. Puede ser mucho y, a la vez, maravilloso.",
  sw2_leap5_ph0: "Es común que haya más llanto, más apego y un sueño inquieto. El bebé puede estar recibiendo mucha información sensorial nueva.",
  sw2_leap5_ph1: "El bebé está absorbiendo muchas imágenes y sonidos nuevos. La irritabilidad puede alcanzar su punto máximo antes de calmarse.",
  sw2_leap5_ph2: "La nueva conciencia sensorial florece: notarás periodos de alerta más largos y una mirada más intencionada.",
  sw2_leap5_sg0: "Llora más de lo habitual",
  sw2_leap5_sg1: "Quiere comer constantemente",
  sw2_leap5_sg2: "Cuesta más calmarlo",
  sw2_leap5_sg3: "Prefiere estar cerca",
  sw2_leap5_sg4: "Se sobresalta más fácilmente",
  sw2_leap5_sg5: "No le gusta que lo desvistan",
  sw2_leap5_sk0: "Reacciona a la luz y al sonido",
  sw2_leap5_sk1: "Sigue con la mirada con más fluidez",
  sw2_leap5_sk2: "Primeras sonrisas sociales",
  sw2_leap5_sk3: "Más periodos de alerta",
  sw2_leap5_sk4: "Se gira hacia tu voz",
  sw2_leap5_sk5: "Nota los patrones de alto contraste",
  sw2_leap5_ac0: "Sostén al bebé mirando hacia afuera para que explore la habitación",
  sw2_leap5_ac1: "Muéstrale tarjetas de alto contraste en blanco y negro",
  sw2_leap5_ac2: "Cuenta en voz alta todo lo que haces",
  sw2_leap5_ac3: "Masaje suave al bebé en momentos tranquilos",
  sw2_leap5_tip: "El contacto piel con piel es muy valioso ahora. Portear y mecer suavemente pueden aliviar los días de más llanto.",
