  sw1_pa_dailyChecklist: "Lista diaria de nutrientes",
  sw1_pa_nutT1: "El ácido fólico es muy importante al principio. Si las náuseas te impiden comer, los snacks suaves y pequeños también cuentan.",
  sw1_pa_nutT2: "El hierro cobra más importancia a medida que crece el volumen de sangre. Combinar alimentos ricos en hierro con vitamina C puede ayudar a absorberlo.",
  sw1_pa_nutT3: "La proteína y el calcio importan mucho ahora, mientras el bebé forma huesos y músculos. Tu profesional de salud puede decirte qué cantidades te convienen.",
