  sw1_pa_movementGuide: "Una guía de movimiento suave",
  sw1_pa_exT1: "Muchas guías sugieren unos 150 minutos de movimiento moderado a la semana, y tu profesional de salud puede adaptarlo a ti. La energía puede bajar al principio: los paseos cortos cuentan.",
  sw1_pa_exT2: "Muchas guías sugieren unos 150 minutos de movimiento moderado a la semana, y tu profesional de salud puede adaptarlo a ti. Nadar, el yoga prenatal y caminar pueden sentarte genial ahora.",
  sw1_pa_exT3: "Muchas guías sugieren unos 150 minutos de movimiento moderado a la semana, y tu profesional de salud puede adaptarlo a ti. Escucha a tu cuerpo: el trabajo del suelo pélvico y el movimiento guiado por la respiración pueden ayudarte a prepararte para el parto.",
