  sw1_pa_c511Pre: "La clásica ",
  sw1_pa_c511Post: ": contracciones con unos 5 minutos de diferencia, de cerca de 1 minuto, durante 1 hora. Antes de las 37 semanas, o si tienes dudas, llama antes a tu profesional de salud.",
  sw1_pa_movement: "Movimiento",
  sw1_pa_guideT1: "Muchas personas registran menos al principio, y está bien. El descanso, el agua y las comidas pequeñas son un buen punto de partida.",
  sw1_pa_guideT2: "Muchas personas sienten que vuelve la energía por esta época, y las náuseas suelen aliviarse. El movimiento y las comidas equilibradas pueden sentar bien.",
