  sw1_pa_blurb_kicks: "Conteos por sesión",
  sw1_pa_blurb_sleep: "Horas por noche",
  sw1_pa_blurb_mood: "Cómo te sientes cada día",
  sw1_pa_blurb_symptoms: "Frecuencia y desglose",
  sw1_pa_blurb_hydration: "Vasos al día",
  sw1_pa_blurb_nutrition: "Lista diaria de nutrientes",
  sw1_pa_blurb_exercise: "Minutos activos al día",
  sw1_pa_blurb_contractions: "Frecuencia e intervalos",
  sw1_pa_blurb_birth: "Plan, maleta y papeles",
  sw1_pa_triNote: "Nota del trimestre {{n}}",
  sw1_pa_kickT1: "La mayoría de las personas sienten los primeros movimientos entre las semanas 16 y 22. Muchas los notan antes en un segundo embarazo.",
  sw1_pa_kickT2: "Los movimientos son cada vez más fuertes y los patrones aún se están asentando. Cuéntale a tu profesional de salud cualquier cosa que te preocupe.",
  sw1_pa_kickT3: "Contar a la misma hora cada día facilita notar los patrones. Muchas personas eligen un momento tranquilo después de comer.",
  sw1_pa_slT1: "El cansancio es habitual al principio. Una siesta corta cuenta. Mantenerte incorporada un rato después de comer puede aliviar el reflujo.",
  sw1_pa_slT2: "Muchas personas duermen algo mejor ahora. Tumbarte de lado con una almohada entre las rodillas puede ser cómodo.",
  sw1_pa_slT3: "Una almohada de cuerpo entero puede ayudar. Muchas personas van al baño justo antes de acostarse y dejan agua cerca para los despertares.",
  sw1_pa_moT1: "Las hormonas cambian rápido, así que el ánimo puede oscilar. Sé amable contigo misma.",
  sw1_pa_moT2: "La energía suele volver por esta época. Si te sientes decaída o ansiosa durante un tiempo, coméntalo en tu próxima visita.",
  sw1_pa_moT3: "Muchas personas se sienten ansiosas antes del parto. Un paseo corto y unos minutos de respiración lenta pueden ayudar.",
  sw1_pa_syT1: "Las náuseas, los pechos sensibles, el cansancio y los dolores de cabeza suelen formar parte de las primeras semanas. Cuéntale a tu profesional de salud si algo te preocupa.",
  sw1_pa_syT2: "Puedes notar molestias por el estiramiento en la parte baja del vientre, algo de hinchazón o calambres en las piernas. Llama a tu profesional de salud si tienes un dolor agudo que no desaparece.",
  sw1_pa_syT3: "La acidez, la hinchazón, el dolor de cadera y las contracciones de Braxton Hicks suelen aumentar ahora. Si tienes un dolor de cabeza intenso repentino o cambios en la vista, llama a tu profesional de salud de inmediato.",
  sw1_pa_wbT1: "Registrar cualquier cosa ya es un buen comienzo. Las primeras semanas son intensas: el ácido fólico, el agua y el sueño son un buen foco.",
  sw1_pa_wbT2: "Una buena etapa para crear hábitos. El movimiento y las comidas variadas merecen un poco de tu tiempo ahora.",
  sw1_pa_wbT3: "Descansar también es parte del trabajo. Protege tu sueño y ve con calma con el movimiento si lo necesitas.",
  sw2_kh_gsleep0: "Las guías para recién nacidos (0-3 meses) sugieren de 14 a 17 horas de sueño al día, siestas incluidas. {{h}}h está en la mitad de ese rango. Cada bebé duerme a su manera.",
  sw2_kh_gsleep1: "A los {{m}} meses, las guías sugieren de 12 a 16 horas al día, con 2 o 3 siestas. {{h}}h es la mitad de ese rango. El ritmo de las siestas suele empezar a asentarse por esta época.",
  sw2_kh_gsleep2: "A los {{m}} meses, las guías sugieren de 12 a 16 horas al día, entre el sueño nocturno y las siestas. Los patrones varían mucho de un bebé a otro.",
  sw2_kh_gsleep3: "Para niños de 12 a 23 meses, las guías sugieren de 11 a 14 horas al día. Muchos pasan a una sola siesta entre los 15 y los 18 meses. {{h}}h es solo un punto de partida.",
  sw2_kh_gsleep4: "A los 2 años, las guías sugieren de 11 a 14 horas al día. Muchos niños aún hacen una siesta a mediodía; algunos empiezan a dejarla cerca de los 3 años.",
  sw2_kh_gsleep5: "Para preescolares, las guías sugieren unas 10 a 13 horas al día, siestas incluidas. Muchos niños ya no hacen siesta a esta edad, así que casi todo el sueño es nocturno. Los niños mayores suelen necesitar un poco menos.",
  sw2_kh_gcal0: "Antes de los 6 meses, toda la nutrición viene de la leche materna o de fórmula, así que aquí no se siguen las calorías. El número de tomas y el volumen dicen más.",
  sw2_kh_gcal1: "A los {{m}} meses se están introduciendo los sólidos y la mayoría de las calorías aún vienen de la leche. {{k}} kcal de sólidos es un punto de partida suave para esta etapa.",
  sw2_kh_gcal2: "Entre los 12 y los 17 meses, la comida sólida gana más espacio en el día. {{k}} kcal es una meta suave para la parte sólida. El apetito puede cambiar de un día a otro.",
  sw2_kh_gcal3: "Entre los 18 y los 23 meses, la comida sólida es la principal fuente de nutrición, a menudo 3 comidas y 1 o 2 meriendas. {{k}} kcal es una meta diaria suave.",
  sw2_kh_gcal4: "A los 2 años, muchos niños hacen 3 comidas y 2 meriendas con todos los grupos de alimentos. {{k}} kcal es una meta diaria suave. El apetito puede cambiar de un día a otro.",
  sw2_kh_gcal5: "Para niños de unos {{y}} años, {{k}} kcal al día es una meta suave, repartida en 3 comidas y 1 o 2 meriendas. El apetito varía de un día a otro.",
  sw2_kh_gfeed0: "Los recién nacidos suelen comer de 8 a 12 veces al día, más o menos cada 2 o 3 horas (guía de la AAP). Comer con frecuencia ayuda a la producción de leche y al crecimiento en las primeras semanas.",
  sw2_kh_gfeed1: "A los {{m}} meses, muchos bebés comen unas 7 a 9 veces al día, y las tomas suelen espaciarse un poco a medida que crecen.",
  sw2_kh_gfeed2: "Los bebés de unos {{m}} meses suelen comer de 6 a 8 veces al día. Algunos empiezan a asentarse en un ritmo más previsible.",
  sw2_kh_gfeed3: "De los 6 a los 11 meses, de {{lo}} a {{hi}} tomas de leche al día es un punto de partida habitual mientras se introducen las comidas sólidas. La leche sigue siendo importante y las tomas van disminuyendo poco a poco.",
  sw2_kh_gfeed4: "Para niños de 12 a 23 meses, {{n}} tomas de leche al día (unos 350-400 ml en total, a menudo por la mañana y a la hora de dormir) es una guía habitual. La leche entera de vaca puede sustituir a la fórmula después de los 12 meses; si tienes dudas, pregunta al pediatra.",
  sw2_kh_gfeed5: "A los 2 años, {{n}} raciones de leche al día (unos 350 ml) pueden aportar calcio y vitamina D. Puede ser leche de vaca, una alternativa vegetal o seguir con el pecho.",
  sw2_kh_gfeed6: "Los niños de unos {{y}} años aún pueden tomar {{n}} vaso(s) de leche al día por el calcio. Es opcional y otros lácteos también sirven.",
  sw2_kh_gml0: "Los recién nacidos suelen tomar de 60 a 90 ml por toma, lo que suma unos 500-700 ml al día. Las cantidades aumentan semana a semana. Las cantidades del pecho son estimadas.",
  sw2_kh_gml1: "A los {{m}} meses, los bebés suelen tomar unos 120-150 ml por toma, más o menos 700-800 ml al día, con tomas menos frecuentes pero más grandes.",
  sw2_kh_gml2: "Alrededor de los {{m}} meses, los bebés suelen tomar de 150 a 180 ml por toma, más o menos 800-950 ml al día, antes de empezar con los sólidos.",
  sw2_kh_gml3: "A medida que aumentan los sólidos, el volumen de leche suele bajar a unos {{ml}} ml al día, así el bebé sigue tomando leche mientras explora los alimentos sólidos.",
  sw2_kh_gml4: "Unos {{ml}} ml de leche al día pueden ayudar a cubrir el calcio (aproximadamente 500-700 mg al día a esta edad) y la vitamina D para unos huesos fuertes.",
  sw2_kh_gml5: "{{ml}} ml de leche al día es una meta razonable de calcio, unas {{c}} taza(s).",
  sw2_kh_gact0: "{{n}} actividades registradas al día te ayudan a seguir la rutina de tu bebé. A esta edad son tomas, cambios de pañal, tiempo boca abajo y cómo se siente.",
  sw2_kh_gact1: "{{n}} actividades al día pueden cubrir tomas, comidas, siestas, juego y estado de ánimo. Registrar te ayuda a notar patrones en la rutina de tu bebé.",
  sw2_kh_gact2: "{{n}} actividades al día pueden cubrir comidas, meriendas, siestas, juego al aire libre y cosas nuevas aprendidas. Registrar con regularidad te ayuda a ver patrones y a compartirlos con quienes cuidan.",
  sw2_kh_gact3: "{{n}} actividades al día dan una imagen completa del día de tu hijo: comidas, juego, hitos y salud. También ayuda en las visitas al pediatra.",
