  sw2_kh_sqGreatTag: "Cerca de la meta",
  sw2_kh_sqGreatBlurb: "La mayoría de los días se acercan a la meta o la superan. Un ritmo constante así es precioso: sigue así.",
  sw2_kh_sqSolidTag: "Casi siempre en la meta",
  sw2_kh_sqSolidBlurb: "El sueño ha sido bastante constante últimamente. Algunas noches más cortas también forman parte del panorama.",
  sw2_kh_sqRestlessTag: "Algo entrecortado",
  sw2_kh_sqRestlessBlurb: "Algunas noches han sido cortas. Puedes probar a adelantar la hora de dormir 15 minutos durante unos días y ver cómo va.",
  sw2_kh_sqPoorTag: "Por debajo de la meta últimamente",
  sw2_kh_sqPoorBlurb: "Muchas noches han sido cortas o interrumpidas. Si lleva una semana así y te preguntas por qué, hablar con el pediatra puede ayudar: una enfermedad, la dentición o cambios de horario pueden influir.",
  sw2_kh_sqNoneTag: "Añade un registro",
  sw2_kh_sqNoneBlurb: "Aún no hay registros de sueño en este período. Registrar aunque sea un sueño ayuda a que se llenen los anillos.",
